mapper.insert:

/* isry.couns.mngr.onlineCnttMng.mapper.GriefSltnAlkoolMapper.InsertGriefSltnAlkoolThema - 개발지원팀 이태호  */        
INSERT INTO AYE400 /* 고민해결백과주제 */
    (GRIEF_SLTN_ALKIOL_THMA_SN
    , TTL_NM
    , SBTLE_NM
    , ATFINO           
    , FRST_RGTR_ID
    , FRST_REG_DT
    , LAST_MDFR_ID
    , LAST_MDFCN_DT
    )
VALUES
    (AYE400_SQ01.NEXTVAL            
    , #{TTL_NM}
    , #{SBTLE_NM}
    , #{ATFINO}            
    , #{FRST_RGTR_ID}
    , SYSDATE
    , #{LAST_MDFR_ID}
    , SYSDATE 
    )

mapper.update:

/* isry.couns.mngr.onlineCnttMng.mapper.GriefSltnAlkoolMapper.DeleteGriefSltnAlkoolThema - 개발지원팀 이태호  */
DELETE AYE400 /* 고민해결백과주제 */            
WHERE GRIEF_SLTN_ALKIOL_THMA_SN = #{GRIEF_SLTN_ALKIOL_THMA_SN}


/* isry.couns.mngr.onlineCnttMng.mapper.GriefSltnAlkoolMapper.DeleteGriefSltnAlkool - 개발지원팀 이태호  */
DELETE AYE410 /* 고민해결백과 */            
WHERE GRIEF_SLTN_ALKIOL_THMA_SN = #{GRIEF_SLTN_ALKIOL_THMA_SN}
  AND GRIEF_SLTN_ALKIOL_SN      = #{GRIEF_SLTN_ALKIOL_SN}


        /* isry.couns.mngr.onlineCnttMng.mapper.GriefSltnAlkoolMapper.UpdateGriefSltnAlkoolThema - 개발지원팀 이태호  */
        UPDATE AYE400 /* 고민해결백과주제 */
		SET TTL_NM          = #{TTL_NM}
		  , SBTLE_NM        = #{SBTLE_NM}
		  , ATFINO          = #{ATFINO}
		  , LAST_MDFR_ID    = #{LAST_MDFR_ID}
		  , LAST_MDFCN_DT   = SYSDATE
		WHERE GRIEF_SLTN_ALKIOL_THMA_SN = #{GRIEF_SLTN_ALKIOL_THMA_SN}


/* isry.couns.mngr.onlineCnttMng.mapper.GriefSltnAlkoolMapper.UpdateGriefSltnAlkool - 개발지원팀 이태호  */
UPDATE AYE410 /* 고민해결백과 */
SET GRIEF_SLTN_ALKIOL_THMA_SN   = #{GRIEF_SLTN_ALKIOL_THMA_SN}
  , TTL_NM                      = #{TTL_NM}
  , SUPRV_NM                    = #{SUPRV_NM}
  , SQNCE_NO                    = #{SQNCE_NO}
  , OPEN_RSVT_DT                = TO_DATE(#{OPEN_RSVT_DT},'YYYY-MM-DD:HH24:MI')          
  , ATFINO                      = #{ATFINO}
  , LAST_MDFR_ID                = #{LAST_MDFR_ID}
  , LAST_MDFCN_DT               = SYSDATE
WHERE GRIEF_SLTN_ALKIOL_THMA_SN = #{GRIEF_SLTN_ALKIOL_THMA_SN}
  AND GRIEF_SLTN_ALKIOL_SN      = #{GRIEF_SLTN_ALKIOL_SN}

mapper.select:
/* isry.couns.mngr.onlineCnttMng.mapper.GriefSltnAlkoolMapper.selectGriefSltnAlkoolList - 개발지원팀 이태호 */ SELECT a.GRIEF_SLTN_ALKIOL_THMA_SN AS GRIEF_SLTN_ALKIOL_THMA_SN ,a.GRIEF_SLTN_ALKIOL_SN AS GRIEF_SLTN_ALKIOL_SN ,a.SQNCE_NO AS SQNCE_NO ,a.TTL_NM AS TTL_NM ,a.SUPRV_NM AS SUPRV_NM ,a.OPEN_RSVT_DT AS OPEN_RSVT_DT ,a.ATFINO AS ATFINO ,TO_CHAR(a.FRST_REG_DT,'YYYY-MM-DD') AS FRST_REG_DT ,C##RG.DEC_B64(c.FLNM_ENCPT) AS FLNM_ENCPT ,a.FRST_RGTR_ID AS FRST_RGTR_ID ,(SELECT x.TTL_NM FROM AYE400 x WHERE x.GRIEF_SLTN_ALKIOL_THMA_SN = a.GRIEF_SLTN_ALKIOL_THMA_SN ) AS GRIEF_THMA FROM AYE410 a ,SAA200 b /* 사용자 */ ,SCA100 c /* 종사자 */ WHERE 1=1 AND a.FRST_RGTR_ID = b.USER_ID AND b.ENFSN_NO = c.ENFSN_NO AND c.DEL_YN = 'N'
AND a.TTL_NM LIKE '%' || #{TTL_NM} || '%'
AND c.FLNM_ENCPT = C##RG.ENC_B64(#{FLNM_ENCPT})
AND a.GRIEF_SLTN_ALKIOL_THMA_SN = #{GRIEF_SLTN_ALKIOL_THMA_SN}
ORDER BY a.GRIEF_SLTN_ALKIOL_THMA_SN ASC ,a.SQNCE_NO DESC
